html:
{%- set currency = doc.currency or "NGN" -%}
{%- set is_debit = doc.intercompany_direction == "Debit Intercompany Account" -%}
{%- set direction_label = "RECEIVABLE" if is_debit else "PAYABLE" -%}
{%- set direction_color = "#1b5e20" if is_debit else "#b71c1c" -%}
{%- set direction_bg    = "#e8f5e9" if is_debit else "#ffebee" -%}

<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8"/>
<meta name="viewport" content="width=device-width, initial-scale=1.0"/>
<title>Intercompany Invoice — {{ doc.name }}</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Playfair+Display:wght@400;700;900&family=DM+Sans:wght@300;400;500;600;700&display=swap');

  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

  :root {
    --ink:        #0d1b2a;
    --ink-soft:   #455a64;
    --rule:       #cfd8dc;
    --accent:     #1a237e;
    --accent-lt:  #e8eaf6;
    --gold:       #c8920a;
    --gold-lt:    #fff8e1;
    --debit:      #1b5e20;
    --credit:     #b71c1c;
    --paper:      #fafafa;
  }

  @page {
    size: A4;
    margin: 12mm 10mm;
  }

  body {
    font-family: 'DM Sans', sans-serif;
    font-size: 10pt;
    color: var(--ink);
    background: var(--paper);
    line-height: 1.5;
  }

  /* ── DOCUMENT WRAPPER ─────────────────────────── */
  .document {
    max-width: 100%;
    margin: 0 auto;
    padding: 0;
  }

  /* ── HEADER ───────────────────────────────────── */
  .header {
    display: grid;
    grid-template-columns: 1fr auto;
    align-items: start;
    gap: 24px;
    border-bottom: 3px solid var(--accent);
    padding-bottom: 18px;
    margin-bottom: 24px;
  }

  .company-block h1 {
    font-family: 'Playfair Display', serif;
    font-size: 22pt;
    font-weight: 900;
    color: var(--accent);
    letter-spacing: -0.5px;
    line-height: 1.1;
  }

  .company-block p {
    color: var(--ink-soft);
    font-size: 9pt;
    margin-top: 4px;
  }

  .doc-meta {
    text-align: right;
  }

  .doc-number {
    font-family: 'Playfair Display', serif;
    font-size: 16pt;
    font-weight: 700;
    color: var(--accent);
  }

  .doc-label {
    font-size: 8pt;
    letter-spacing: 3px;
    text-transform: uppercase;
    color: var(--gold);
    font-weight: 600;
    display: block;
    margin-bottom: 4px;
  }

  .direction-badge {
    display: inline-block;
    margin-top: 8px;
    padding: 5px 14px;
    border-radius: 20px;
    font-size: 9pt;
    font-weight: 700;
    letter-spacing: 1px;
    background: {{ direction_bg }};
    color: {{ direction_color }};
    border: 1.5px solid {{ direction_color }};
  }

  /* ── PARTY BLOCK ──────────────────────────────── */
  .parties {
    display: grid;
    grid-template-columns: 1fr 40px 1fr;
    gap: 0;
    margin-bottom: 22px;
    align-items: center;
  }

  .party-box {
    background: var(--accent-lt);
    border-radius: 8px;
    padding: 14px 16px;
    border-top: 3px solid var(--accent);
  }

  .party-box.counterparty {
    background: #fff3e0;
    border-top-color: var(--gold);
  }

  .party-role {
    font-size: 8pt;
    letter-spacing: 2px;
    text-transform: uppercase;
    color: var(--ink-soft);
    margin-bottom: 4px;
    font-weight: 600;
  }

  .party-name {
    font-family: 'Playfair Display', serif;
    font-size: 13pt;
    font-weight: 700;
    color: var(--ink);
  }

  .arrow-cell {
    text-align: center;
    font-size: 20pt;
    color: var(--accent);
    font-weight: 900;
  }

  /* ── META GRID ────────────────────────────────── */
  .meta-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 1px;
    background: var(--rule);
    border: 1px solid var(--rule);
    border-radius: 6px;
    overflow: hidden;
    margin-bottom: 22px;
    
  }

  .meta-cell {
    background: #fff;
    padding: 10px 13px;
  }

  .meta-cell .lbl { font-size: 8pt; color: var(--ink-soft); text-transform: uppercase; letter-spacing: 1px; }
  .meta-cell .val { font-size: 10.5pt; font-weight: 600; margin-top: 2px; }

  /* ── SECTION TITLES ───────────────────────────── */
  .section-title {
    font-family: 'Playfair Display', serif;
    font-size: 11pt;
    font-weight: 700;
    color: var(--accent);
    border-bottom: 2px solid var(--accent);
    padding-bottom: 5px;
    margin: 22px 0 12px;
    letter-spacing: 0.2px;
  }

  .section-title span {
    font-family: 'DM Sans', sans-serif;
    font-size: 8pt;
    color: var(--ink-soft);
    font-weight: 400;
    letter-spacing: 2px;
    text-transform: uppercase;
    margin-left: 8px;
  }

  /* ── TABLES ───────────────────────────────────── */
  table {
    width: 100%;
    border-collapse: collapse;
    font-size: 9pt;
    table-layout: auto;
  }

  thead tr {
    background: var(--accent);
    color: #fff;
  }

  thead th {
    padding: 9px 8px;
    text-align: right;
    font-weight: 600;
    letter-spacing: 0.3px;
    font-size: 8pt;
    white-space: nowrap;
  }

  thead th:first-child { text-align: left; }

  tbody tr:nth-child(even) { background: #f5f5f5; }
  tbody tr:hover { background: var(--accent-lt); }

  tbody td {
    padding: 8px 8px;
    text-align: right;
    border-bottom: 1px solid var(--rule);
    vertical-align: top;
  }

  tbody td:first-child { text-align: left; }

  tfoot tr {
    background: var(--accent-lt);
    font-weight: 700;
    border-top: 2px solid var(--accent);
  }

  tfoot td {
    padding: 9px 8px;
    text-align: right;
  }

  tfoot td:first-child { text-align: left; }

  /* ── ITEMS TABLE SPECIFIC ─────────────────────── */
  .items-table thead th.item-col {
    width: 35%;
    text-align: left;
    color: #fff !important;
  }
  
  .items-table thead th.amount-col {
    width: 18.75%;
    color: #fff !important;
  }
  
  .items-table tbody td.item-col {
    text-align: left;

  }

  /* ── SUMMARY BOX ──────────────────────────────── */
  .summary-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    margin: 22px 0;
  }

  .summary-table {
    border: 1px solid var(--rule);
    border-radius: 8px;
    overflow: hidden;
  }

  .summary-table table thead tr { background: var(--gold); }
  .summary-table.interest table thead tr { background: #e65100; }
  .summary-table.tax table thead tr { background: #4a148c; }

  /* ── TOTALS BLOCK ─────────────────────────────── */
  .totals-block {
    margin-left: auto;
    width: 340px;
    border: 1px solid var(--rule);
    border-radius: 8px;
    overflow: hidden;
    margin-top: 14px;
  }

  .totals-block table thead tr { background: #37474f; }

  .grand-row td {
    background: var(--accent) !important;
    color: #fff !important;
    font-size: 12pt !important;
    font-family: 'Playfair Display', serif;
    padding: 11px 14px !important;
  }

  .wht-row td { color: var(--credit); font-style: italic; }

  /* ── AMORTIZATION TABLE ───────────────────────── */
  .amort-table thead tr { background: #0d47a1; }
  .amort-table tfoot tr { background: #e3f2fd; border-top: 2px solid #0d47a1; }
  .amort-table .principal-col { color: #0d47a1; font-weight: 600; }
  .amort-table .interest-col  { color: #e65100; }
  .amort-table .balance-col   { font-weight: 600; }

  /* ── INTEREST ACCRUAL ─────────────────────────── */
  .accrual-table thead tr { background: #bf360c; }
  .accrual-table tfoot tr { background: #fff3e0; border-top: 2px solid #bf360c; }

  /* ── TAX BREAKDOWN ────────────────────────────── */
  .tax-table thead tr { background: #4a148c; }
  .tax-table tfoot tr { background: #f3e5f5; border-top: 2px solid #4a148c; }

  .badge {
    display: inline-block;
    padding: 2px 8px;
    border-radius: 10px;
    font-size: 8pt;
    font-weight: 600;
    color: #fff;
  }
  .badge-vat  { background: #2e7d32; }
  .badge-wht  { background: #b71c1c; }
  .badge-item { background: #1565c0; }

  /* ── GL ACCOUNTS ──────────────────────────────── */
  .gl-box {
    background: #f5f5f5;
    border-radius: 8px;
    padding: 14px 16px;
    border-left: 4px solid var(--accent);
    margin-bottom: 10px;
  }

  .gl-box .lbl { font-size: 8pt; color: var(--ink-soft); text-transform: uppercase; letter-spacing: 1px; }
  .gl-box .val { font-size: 10pt; font-weight: 600; margin-top: 2px; font-family: monospace; }

  /* ── FOOTER ───────────────────────────────────── */
  .doc-footer {
    border-top: 2px solid var(--accent);
    margin-top: 32px;
    padding-top: 14px;
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    gap: 20px;
    font-size: 8.5pt;
    color: var(--ink-soft);
  }

  .sig-line {
    border-top: 1px solid var(--ink);
    margin-top: 36px;
    padding-top: 5px;
    font-size: 8pt;
    color: var(--ink-soft);
  }

  .watermark {
    text-align: center;
    margin-top: 8px;
    font-size: 7.5pt;
    color: #b0bec5;
    letter-spacing: 1px;
  }

  .page-break { page-break-before: always; }

  .notice {
    background: var(--gold-lt);
    border: 1px solid var(--gold);
    border-left: 4px solid var(--gold);
    border-radius: 6px;
    padding: 10px 14px;
    font-size: 9pt;
    color: #5d4037;
    margin: 14px 0;
  }

  .num { font-variant-numeric: tabular-nums; }
</style>
</head>
<body>
<div class="document">

  <!-- ═══════════════════════════════════════════
       HEADER
  ══════════════════════════════════════════════ -->
  <div class="header">
    <div class="company-block">
      <h1>{{ doc.company }}</h1>
      <p>Intercompany Transaction Document</p>
      {% if doc.transaction_type %}
      <p style="margin-top:6px;font-size:9pt;color:var(--gold);font-weight:600;letter-spacing:1px;text-transform:uppercase;">
        {{ doc.transaction_type }}
      </p>
      {% endif %}
    </div>
    <div class="doc-meta">
      <span class="doc-label">Document No.</span>
      <div class="doc-number">{{ doc.name }}</div>
      <div style="margin-top:6px;font-size:9pt;color:var(--ink-soft);">
        Posted: <strong>{{ frappe.format(doc.posting_date, {"fieldtype":"Date"}) }}</strong>
      </div>
      {% if doc.due_date %}
      <div style="font-size:9pt;color:var(--ink-soft);">
        Due: <strong>{{ frappe.format(doc.due_date, {"fieldtype":"Date"}) }}</strong>
      </div>
      {% endif %}
      <div class="direction-badge">{{ direction_label }}</div>
    </div>
  </div>

  <!-- ═══════════════════════════════════════════
       PARTIES
  ══════════════════════════════════════════════ -->
  <div class="parties">
    <div class="party-box">
      <div class="party-role">Issuing Entity</div>
      <div class="party-name">{{ doc.company }}</div>
      {% if doc.intercompany_account %}
      <div style="font-size:8.5pt;color:var(--ink-soft);margin-top:6px;">
        IC Account: <strong>{{ doc.intercompany_account }}</strong>
      </div>
      {% endif %}
    </div>
    <div class="arrow-cell">{% if is_debit %}→{% else %}←{% endif %}</div>
    <div class="party-box counterparty">
      <div class="party-role" style="color:#a0522d;">Counterparty Entity</div>
      <div class="party-name">{{ doc.counterparty_company }}</div>
      {% if doc.counterparty_intercompany_account %}
      <div style="font-size:8.5pt;color:var(--ink-soft);margin-top:6px;">
        IC Account: <strong>{{ doc.counterparty_intercompany_account }}</strong>
      </div>
      {% endif %}
    </div>
  </div>

  <!-- ═══════════════════════════════════════════
       META GRID
  ══════════════════════════════════════════════ -->
  <div class="meta-grid">
    <div class="meta-cell">
      <div class="lbl">Currency</div>
      <div class="val">{{ doc.currency }}</div>
    </div>
    <div class="meta-cell">
      <div class="lbl">Exchange Rate</div>
      <div class="val">{{ doc.exchange_rate or 1 }}</div>
    </div>
    <div class="meta-cell">
      <div class="lbl">Status</div>
      <div class="val">{{ doc.status }}</div>
    </div>
    <div class="meta-cell">
      <div class="lbl">GL Status</div>
      <div class="val">{{ doc.gl_entry_status or "Pending" }}</div>
    </div>
    {% if doc.journal_entry %}
    <div class="meta-cell">
      <div class="lbl">Journal Entry</div>
      <div class="val">{{ doc.journal_entry }}</div>
    </div>
    {% endif %}
    {% if doc.reference_name %}
    <div class="meta-cell">
      <div class="lbl">Reference</div>
      <div class="val">{{ doc.reference_name }}</div>
    </div>
    {% endif %}
  </div>

  <!-- ═══════════════════════════════════════════
       ITEMS TABLE
  ══════════════════════════════════════════════ -->
  <div class="section-title">
    Schedule I <span>Items &amp; Services</span>
  </div>

  <table class="items-table">
    <thead>
      <tr>
        <th class="item-col">Trans Description</th>
        <th class="amount-col">Amount</th>
        <th class="amount-col">Tax Amount</th>
        <th class="amount-col">Interest Amount</th>
        <th class="amount-col">Line Total</th>
      </tr>
    </thead>
    <tbody>
      {% for row in doc.items %}
      <tr>
        <td class="item-col">
          <strong>{{ row.item_name }}</strong>
          {% if row.description %}<br/><span style="font-size:8pt;color:var(--ink-soft);">{{ row.description }}</span>{% endif %}
        </td>
        <td class="num">{{ frappe.format(row.amount, {"fieldtype":"Currency","currency":currency}) }}</td>
        <td class="num">{{ frappe.format(row.tax_amount, {"fieldtype":"Currency","currency":currency}) }}</td>
        <td class="num">{{ frappe.format(row.interest_amount, {"fieldtype":"Currency","currency":currency}) }}</td>
        <td class="num" style="font-weight:700;">{{ frappe.format(row.line_total, {"fieldtype":"Currency","currency":currency}) }}</td>
      </tr>
      {% endfor %}
    </tbody>
    <tfoot>
      <tr>
        <td>Subtotals</td>
        <td class="num">{{ frappe.format(doc.total_base_amount, {"fieldtype":"Currency","currency":currency}) }}</td>
        <td class="num">{{ frappe.format(doc.total_tax_amount, {"fieldtype":"Currency","currency":currency}) }}</td>
        <td class="num">{{ frappe.format(doc.total_interest_amount, {"fieldtype":"Currency","currency":currency}) }}</td>
        <td class="num" style="font-size:11pt;">{{ frappe.format(doc.grand_total, {"fieldtype":"Currency","currency":currency}) }}</td>
      </tr>
    </tfoot>
  </table>

  <!-- ═══════════════════════════════════════════
       SUMMARY SCHEDULES (2-column)
  ══════════════════════════════════════════════ -->
  <div class="summary-grid">

    <!-- TAX SCHEDULE -->
    <div class="summary-table tax">
      <div class="section-title" style="margin:12px 12px 0;padding-bottom:4px;">Schedule II <span>Tax Analysis</span></div>
      <table class="tax-table">
        <thead>
          <tr>
            <th style="text-align:left;">Component</th>
            <th>Rate</th>
            <th>Base</th>
            <th>Amount</th>
          </tr>
        </thead>
        <tbody>
          {% for row in doc.items %}
          {% if row.tax_amount %}
          <tr>
            <td style="text-align:left;">
              <span class="badge badge-item">ITEM</span> {{ row.item_name }}
            </td>
            <td class="num">{{ row.tax_rate }}%</td>
            <td class="num">{{ frappe.format(row.amount, {"fieldtype":"Currency","currency":currency}) }}</td>
            <td class="num">{{ frappe.format(row.tax_amount, {"fieldtype":"Currency","currency":currency}) }}</td>
          </tr>
          {% endif %}
          {% endfor %}
          {% if doc.vat_amount %}
          <tr>
            <td style="text-align:left;"><span class="badge badge-vat">VAT</span> Value Added Tax</td>
            <td class="num">{{ doc.vat_rate }}%</td>
            <td class="num">{{ frappe.format(doc.total_base_amount, {"fieldtype":"Currency","currency":currency}) }}</td>
            <td class="num">{{ frappe.format(doc.vat_amount, {"fieldtype":"Currency","currency":currency}) }}</td>
          </tr>
          {% endif %}
          {% if doc.withholding_tax_amount %}
          <tr style="color:var(--credit);">
            <td style="text-align:left;"><span class="badge badge-wht">WHT</span> Withholding Tax</td>
            <td class="num">{{ doc.withholding_tax_rate }}%</td>
            <td class="num">{{ frappe.format(doc.total_base_amount, {"fieldtype":"Currency","currency":currency}) }}</td>
            <td class="num">({{ frappe.format(doc.withholding_tax_amount, {"fieldtype":"Currency","currency":currency}) }})</td>
          </tr>
          {% endif %}
        </tbody>
        <tfoot>
          <tr>
            <td colspan="3">Net Tax Effect</td>
            <td class="num">
              {{ frappe.format(
                  (doc.total_tax_amount or 0) - (doc.withholding_tax_amount or 0),
                  {"fieldtype":"Currency","currency":currency}
              ) }}
            </td>
          </tr>
        </tfoot>
      </table>
      <div class="notice" style="margin:10px;font-size:8pt;">
        ⚠ WHT deducted at source. Remit to FIRS via e-TaxPay within 21 days of credit.
      </div>
    </div>

    <!-- INTEREST SCHEDULE -->
    <div class="summary-table interest">
      <div class="section-title" style="margin:12px 12px 0;padding-bottom:4px;">Schedule III <span>Interest (Arms-Length)</span></div>
      {% if doc.interest_period_from and doc.annual_interest_rate %}
      <table class="accrual-table">
        <thead>
          <tr>
            <th style="text-align:left;">Parameter</th>
            <th>Value</th>
          </tr>
        </thead>
        <tbody>
          <tr>
            <td style="text-align:left;">Principal Base</td>
            <td class="num">{{ frappe.format(doc.total_base_amount, {"fieldtype":"Currency","currency":currency}) }}</td>
          </tr>
          <tr>
            <td style="text-align:left;">Period From</td>
            <td class="num">{{ frappe.format(doc.interest_period_from, {"fieldtype":"Date"}) }}</td>
          </tr>
          <tr>
            <td style="text-align:left;">Period To</td>
            <td class="num">{{ frappe.format(doc.interest_period_to, {"fieldtype":"Date"}) }}</td>
          </tr>
          <tr>
            <td style="text-align:left;">Days Outstanding</td>
            <td class="num">{{ doc.days_outstanding }}</td>
          </tr>
          <tr>
            <td style="text-align:left;">Annual Rate (p.a.)</td>
            <td class="num">{{ doc.annual_interest_rate }}%</td>
          </tr>
          <tr>
            <td style="text-align:left;">Day Count Basis</td>
            <td class="num">{{ doc.interest_basis }}</td>
          </tr>
          {% set div = 365 if "365" in (doc.interest_basis or "") else 360 %}
          <tr>
            <td style="text-align:left;">Daily Rate</td>
            <td class="num">{{ "%.6f"|format(doc.annual_interest_rate / 100 / div) }}%</td>
          </tr>
        </tbody>
        <tfoot>
          <tr>
            <td>Total Interest Charged</td>
            <td class="num" style="font-size:11pt;color:var(--credit);">
              {{ frappe.format(doc.total_interest_charged, {"fieldtype":"Currency","currency":currency}) }}
            </td>
          </tr>
        </tfoot>
      </table>
      <div class="notice" style="margin:10px;font-size:8pt;">
        ✓ Rate set at arms-length per OECD Transfer Pricing Guidelines / FIRS TP Regulations 2018.
      </div>
      {% else %}
      <div style="padding:20px;color:var(--ink-soft);font-size:9pt;font-style:italic;">
        No arms-length interest period specified.
      </div>
      {% endif %}

      {% if doc.total_interest_amount %}
      <table style="margin-top:6px;">
        <thead>
          <tr style="background:#880e4f;">
            <th style="text-align:left;">Interest Source</th>
            <th>Amount</th>
          </tr>
        </thead>
        <tbody>
          {% for row in doc.items %}
          {% if row.interest_amount %}
          <tr>
            <td style="text-align:left;">Line {{ row.idx }}: {{ row.item_name }}</td>
            <td class="num">{{ frappe.format(row.interest_amount, {"fieldtype":"Currency","currency":currency}) }}</td>
          </tr>
          {% endif %}
          {% endfor %}
          {% if doc.total_interest_charged %}
          <tr>
            <td style="text-align:left;">Document-Level Interest</td>
            <td class="num">{{ frappe.format(doc.total_interest_charged, {"fieldtype":"Currency","currency":currency}) }}</td>
          </tr>
          {% endif %}
        </tbody>
        <tfoot>
          <tr>
            <td>Total Interest</td>
            <td class="num">{{ frappe.format(doc.total_interest_amount, {"fieldtype":"Currency","currency":currency}) }}</td>
          </tr>
        </tfoot>
      </table>
      {% endif %}
    </div>
  </div>

  <!-- ═══════════════════════════════════════════
       TOTALS BLOCK
  ══════════════════════════════════════════════ -->
  <div style="display:flex;justify-content:flex-end;">
    <div class="totals-block">
      <table>
        <thead>
          <tr><th colspan="2" style="text-align:center;letter-spacing:2px;font-size:9pt;">SETTLEMENT SUMMARY</th></tr>
        </thead>
        <tbody>
          <tr>
            <td style="text-align:left;">Base Amount</td>
            <td class="num">{{ frappe.format(doc.total_base_amount, {"fieldtype":"Currency","currency":currency}) }}</td>
          </tr>
          <tr>
            <td style="text-align:left;">Total Tax</td>
            <td class="num">{{ frappe.format(doc.total_tax_amount, {"fieldtype":"Currency","currency":currency}) }}</td>
          </tr>
          <tr>
            <td style="text-align:left;">Total Interest</td>
            <td class="num">{{ frappe.format(doc.total_interest_amount, {"fieldtype":"Currency","currency":currency}) }}</td>
          </tr>
          {% if doc.withholding_tax_amount %}
          <tr class="wht-row">
            <td style="text-align:left;">Less: WHT ({{ doc.withholding_tax_rate }}%)</td>
            <td class="num">({{ frappe.format(doc.withholding_tax_amount, {"fieldtype":"Currency","currency":currency}) }})</td>
          </tr>
          {% endif %}
        </tbody>
        <tfoot>
          <tr class="grand-row">
            <td style="text-align:left;">NET PAYABLE / RECEIVABLE</td>
            <td class="num">{{ frappe.format(doc.grand_total, {"fieldtype":"Currency","currency":currency}) }}</td>
          </tr>
        </tfoot>
      </table>
    </div>
  </div>

  <!-- ═══════════════════════════════════════════
       PAGE 2 — AMORTIZATION SCHEDULE
  ══════════════════════════════════════════════ -->
  {% if doc.annual_interest_rate and doc.total_base_amount %}
  <div class="page-break">
    <div class="section-title" style="margin-top:0;">
      Schedule IV <span>Loan Amortization — Illustrative (Monthly, Equal Instalments)</span>
    </div>

    <div class="notice">
      📊 This amortization schedule is computed on a <strong>reducing balance</strong> basis using the PMT formula.
      Principal = {{ frappe.format(doc.total_base_amount, {"fieldtype":"Currency","currency":currency}) }},
      Rate = {{ doc.annual_interest_rate }}% p.a. ({{ (doc.annual_interest_rate / 12) | round(4) }}% per month),
      Day Count: {{ doc.interest_basis or "Actual/365" }}.
      For the full dynamic schedule with configurable periods, use the in-app Amortization Schedule button.
    </div>

    {%- set principal = doc.total_base_amount | float -%}
    {%- set annual_rate = doc.annual_interest_rate | float -%}
    {%- set period_rate = annual_rate / 100 / 12 -%}
    {%- set periods = 12 -%}

    {# PMT calculation via Jinja #}
    {%- if period_rate != 0 -%}
      {%- set pmt_denom = 1 - (1 + period_rate) ** (-periods) -%}
      {%- set instalment = (principal * period_rate / pmt_denom) | round(2) -%}
    {%- else -%}
      {%- set instalment = (principal / periods) | round(2) -%}
    {%- endif -%}

    <table class="amort-table">
      <thead>
        <tr>
          <th>#</th>
          <th>Opening Balance</th>
          <th>Instalment</th>
          <th>Principal</th>
          <th>Interest</th>
          <th>Closing Balance</th>
          <th>Cum. Principal</th>
          <th>Cum. Interest</th>
        </tr>
      </thead>
      <tbody>
        {%- set ns = namespace(balance=principal, cum_p=0, cum_i=0) -%}
        {%- for i in range(1, periods + 1) -%}
          {%- set interest_comp = (ns.balance * period_rate) | round(2) -%}
          {%- set principal_comp = (instalment - interest_comp) | round(2) -%}
          {%- set ns.balance = (ns.balance - principal_comp) | round(2) -%}
          {%- set ns.cum_p = (ns.cum_p + principal_comp) | round(2) -%}
          {%- set ns.cum_i = (ns.cum_i + interest_comp) | round(2) -%}
        <tr>
          <td>{{ i }}</td>
          <td class="num">{{ frappe.format((ns.balance + principal_comp), {"fieldtype":"Currency","currency":currency}) }}</td>
          <td class="num" style="font-weight:600;">{{ frappe.format(instalment, {"fieldtype":"Currency","currency":currency}) }}</td>
          <td class="num principal-col">{{ frappe.format(principal_comp, {"fieldtype":"Currency","currency":currency}) }}</td>
          <td class="num interest-col">{{ frappe.format(interest_comp, {"fieldtype":"Currency","currency":currency}) }}</td>
          <td class="num balance-col">{{ frappe.format([ns.balance, 0] | max, {"fieldtype":"Currency","currency":currency}) }}</td>
          <td class="num" style="color:var(--debit);">{{ frappe.format(ns.cum_p, {"fieldtype":"Currency","currency":currency}) }}</td>
          <td class="num" style="color:var(--credit);">{{ frappe.format(ns.cum_i, {"fieldtype":"Currency","currency":currency}) }}</td>
        </tr>
        {%- endfor -%}
      </tbody>
      <tfoot>
        <tr>
          <td colspan="3">12-Month Totals</td>
          <td class="num principal-col">{{ frappe.format(ns.cum_p, {"fieldtype":"Currency","currency":currency}) }}</td>
          <td class="num interest-col">{{ frappe.format(ns.cum_i, {"fieldtype":"Currency","currency":currency}) }}</td>
          <td colspan="3"></td>
        </tr>
      </tfoot>
    </table>
  </div>
  {% endif %}

  <!-- ═══════════════════════════════════════════
       GL MAPPING
  ══════════════════════════════════════════════ -->
  <div class="section-title" style="margin-top:22px;">
    Schedule V <span>GL Account Mapping</span>
  </div>
  <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:22px;">
    <div class="gl-box">
      <div class="lbl">Intercompany Account — {{ doc.company }}</div>
      <div class="val">{{ doc.intercompany_account or "Not Set" }}</div>
      <div style="margin-top:6px;font-size:8pt;color:{{ direction_color }};font-weight:700;">
        {{ "DR — Debit (Receivable)" if is_debit else "CR — Credit (Payable)" }}
      </div>
    </div>
    <div class="gl-box" style="border-left-color:var(--gold);">
      <div class="lbl">Intercompany Account — {{ doc.counterparty_company }}</div>
      <div class="val">{{ doc.counterparty_intercompany_account or "Mirror entry in counterparty books" }}</div>
      <div style="margin-top:6px;font-size:8pt;color:var(--gold);font-weight:700;">
        {{ "CR — Credit (Payable)" if is_debit else "DR — Debit (Receivable)" }}
      </div>
    </div>
  </div>

  <!-- ═══════════════════════════════════════════
       REMARKS
  ══════════════════════════════════════════════ -->
  {% if doc.remarks %}
  <div style="background:#fff8e1;border:1px solid var(--gold);border-left:4px solid var(--gold);border-radius:6px;padding:12px 14px;margin-bottom:20px;">
    <div style="font-size:8pt;color:#a0522d;text-transform:uppercase;letter-spacing:1px;font-weight:600;margin-bottom:4px;">Remarks</div>
    <div>{{ doc.remarks }}</div>
  </div>
  {% endif %}

  <!-- ═══════════════════════════════════════════
       FOOTER / SIGNATURES
  ══════════════════════════════════════════════ -->
  <div class="doc-footer">
    <div>
      <div class="sig-line">Prepared by</div>
    </div>
    <div>
      <div class="sig-line">Reviewed by (Finance)</div>
    </div>
    <div>
      <div class="sig-line">Approved by (CFO / GM)</div>
    </div>
  </div>

  <div class="watermark" style="margin-top:18px;">
    Generated by Ecclesia · Value Impacts Consulting · {{ doc.name }} · {{ frappe.format(frappe.utils.nowdate(), {"fieldtype":"Date"}) }}
    · This document is computer-generated and constitutes a valid intercompany transaction record.
  </div>

</div>
</body>
</html>
